// Spec: 0002-machine-probe-contract FR-001
/**
 * What a probe answers: three requests (`facts`, `version`, and one osquery SELECT). A request that is none of the three is refused here, before anything is run, and the script on the machine refuses it again. How a probe is
 * reached is the ssh target of Headless, and the line of `authorized_keys` that restricts a key to it is generated by the inbound surface of Headless (see the physical layer).
 *
 * @example
 * ```ts
 * import { parseRequest, encodeRequest } from "./requests.ts";
 * const r = parseRequest("facts"); // { kind: "ok", value: { kind: "facts" } }
 * encodeRequest({ kind: "osquery", sql: "SELECT 1" }); // "osquery U0VMRUNUIDE="
 * ```
 *
 * @module
 */
import { err, ok, type Result } from "@intellectual-frontiers/core";
import { refusal } from "@intellectual-frontiers/lang-sql/aide/guard";
import { dialect as sqlite } from "@intellectual-frontiers/lang-sql/dialects/sqlite";

/** The name of the probe program on a machine. */
export const PROBE_PROGRAM = "machine-probe";

/** Where the probe is installed for the account that runs it, relative to its home folder (the forced command runs from there): no root, nothing listening. */
export const PROBE_PATH = `.local/bin/${PROBE_PROGRAM}`;

/** A request: the facts of the machine, the version of the probe, or one osquery SELECT. */
export type ProbeRequest = { readonly kind: "facts" } | { readonly kind: "version" } | { readonly kind: "osquery"; readonly sql: string };

function base64(text: string): string {
  return btoa(String.fromCharCode(...new TextEncoder().encode(text)));
}

function fromBase64(text: string): string | undefined {
  try {
    return new TextDecoder().decode(Uint8Array.from(atob(text), (c) => c.charCodeAt(0)));
  } catch {
    return undefined;
  }
}

/** The text of a request as sent to the probe: `facts`, `version` or `osquery <base64 of the SELECT>`. */
export function encodeRequest(r: ProbeRequest): string {
  return r.kind === "osquery" ? `osquery ${base64(r.sql)}` : r.kind;
}

/** A request from its text, or why it is refused: only `facts`, `version` and `osquery <base64>` of one statement that only reads, as the guard of the SQL language library judges it by its tree in the SQLite dialect of osquery (no second statement, no write). */
export function parseRequest(text: string): Result<ProbeRequest, string> {
  if (text === "facts") return ok({ kind: "facts" });
  if (text === "version") return ok({ kind: "version" });
  if (!text.startsWith("osquery ")) return err(`unknown probe: ${JSON.stringify(text)} (facts, version, osquery)`);
  const sql = fromBase64(text.slice("osquery ".length).trim());
  if (sql === undefined) return err("the query is not base64");
  const trimmed = sql.trim().replace(/[\s;]+$/, "");
  if (trimmed === "") return err("only SELECT");
  const why = refusal(trimmed, sqlite);
  if (why !== undefined) return err(why);
  return ok({ kind: "osquery", sql: trimmed });
}

/**
 * How to reach a machine for observation: the account the probe runs as, the address and port, and the name of the key made for the probe. The name is a reference: the key itself is kept outside the repository, where only the machine that observes has it.
 *
 * @example
 * ```ts
 * import type { ProbeReach } from "./requests.ts";
 * const reach: ProbeReach = { address: "sparta.example", user: "admin", credential: "sparta-probe" };
 * ```
 */
export type ProbeReach = { readonly address: string; readonly port?: number; readonly user: string; readonly credential: string };
